type Context = { routeKey: string; req: any; res: any; data?: any };
interface Processor { handle(ctx: Context, next: () => Promise<void>): Promise<void>; }
interface RouteConfig { path: string; method: string; pre: Processor[]; handlers: Processor[]; post: Processor[]; }
class Registry { private routes = new Map<string, RouteConfig>(); register(key: string, cfg: RouteConfig) { this.routes.set(key, cfg); } get(key: string) { return this.routes.get(key); } }
async function runPipeline(ctx: Context, cfg: RouteConfig) {
  for (const p of cfg.pre) await p.handle(ctx, () => Promise.resolve());
  for (const h of cfg.handlers) await h.handle(ctx, () => Promise.resolve());
  for (const po of cfg.post) await po.handle(ctx, () => Promise.resolve());
  return ctx;
}
```

