// TypeScript skeleton
export interface MemoizationStrategy<K, V> {
  get(key: K): V | undefined;
  put(key: K, value: V): void;
  invalidate(key: K): void;
  clear(): void;
}
export type StrategyFactory<K, V> = () => MemoizationStrategy<K, V>;

export class Registry<K, V> {
  private map = new Map<string, StrategyFactory<K, V>>();
  register(name: string, factory: StrategyFactory<K, V>) { this.map.set(name, factory); }
  create(name: string): MemoizationStrategy<K, V> | undefined {
    const f = this.map.get(name);
    return f ? f() : undefined;
  }
}
